# Render with a quick matplotlib 3D scatter + bonds by distance cutoff
import numpy as np
import matplotlib
matplotlib.use('Agg')
import matplotlib.pyplot as plt

def read_xyz(fn):
    with open(fn) as f:
        n = int(f.readline())
        f.readline()
        els, coords = [], []
        for _ in range(n):
            p = f.readline().split()
            els.append(p[0]); coords.append([float(x) for x in p[1:4]])
    return els, np.array(coords)

els, xyz = read_xyz('xtbopt.xyz')
col = {'Tc':'purple','S':'yellow','P':'orange','C':'gray','H':'white'}
rcut = {'Tc':2.8,'S':2.2,'P':2.2,'C':1.8,'H':1.3}
fig = plt.figure(figsize=(8,8))
ax = fig.add_subplot(111, projection='3d')
n = len(els)
for i in range(n):
    for j in range(i+1,n):
        d = np.linalg.norm(xyz[i]-xyz[j])
        if d < rcut[els[i]] + 0.3 and d < rcut[els[j]]+0.3:
            ax.plot([xyz[i,0],xyz[j,0]],[xyz[i,1],xyz[j,1]],[xyz[i,2],xyz[j,2]],'k-',lw=1)
for i,e in enumerate(els):
    ax.scatter(*xyz[i], c=col[e], s=40 if e=='H' else 120, edgecolors='k')
    if e != 'H': ax.text(*xyz[i], f"{e}{i}", fontsize=7)
ax.set_box_aspect([1,1,1])
plt.savefig('check.png', dpi=110)
print("saved")
